<script setup>
import { ref, onMounted, onUnmounted, watch } from 'vue';
import PrimaryButtonHome from '@/Components/PrimaryButtonHome.vue';

const props =
    defineProps({
        end: {
            type: Boolean,
            default: false
        },
        start: {
            type: Boolean,
            default: false
        },
    });


const screenResolution = ref(window.screen.width);

const handleResize = () => {
    screenResolution.value = window.screen.width;
};



onMounted(() => {
    window.addEventListener('resize', handleResize);
    window.scrollTo({
        top: 0,
        behavior: 'smooth'
    });
});

onUnmounted(() => {
    window.removeEventListener('resize', handleResize);
});



</script>

